window.TXB=window.TXB||{};TXB["alab/Mar"]={"1:1":"هذه بداية إنجيل يسوع المسيح ابن الله:","1:2":"كما كتب في كتاب إشعياء:«ها أنا أرسل قدامك رسولي الذي يعد لك الطريق؛","1:3":"صوت مناد في البرية: أعدوا طريق الرب، واجعلوا سبله مستقيمة!»","1:4":"فقد ظهر يوحنا المعمدان في البرية ينادي بمعمودية التوبة لمغفرة الخطايا.","1:5":"وخرج إليه أهل منطقة اليهودية وأهل أورشليم جميعا، فكانوا يتعمدون على يده في نهر الأردن معترفين بخطاياهم.","1:6":"وكان يوحنا يلبس ثوبا من وبر الجمال، ويلف وسطه بحزام من جلد، ويقتات الجراد والعسل البري.","1:7":"وكان يعظ قائلا: «سيأتي بعدي من هو أقدر مني، من لا أستحق أن أنحني لأحل رباط حذائه.","1:8":"أنا عمدتكم بالماء؛ أما هو فسوف يعمدكم بالروح القدس».","1:9":"في تلك الأيام جاء يسوع من الناصرة بمنطقة الجليل، وتعمد في نهر الأردن على يد يوحنا.","1:10":"وحالما صعد من الماء، رأى السماوات قد انفتحت، والروح القدس هابطا عليه كأنه حمامة،","1:11":"وإذا صوت من السماوات يقول: «أنت ابني الحبيب، بك سررت كل سرور! »","1:12":"وفي الحال اقتاد الروح يسوع إلى البرية،","1:13":"فقضى فيها أربعين يوما والشيطان يجربه. وكان بين الوحوش وملائكة تخدمه.","1:14":"وبعدما ألقي القبض على يوحنا، انطلق يسوع إلى منطقة الجليل، يبشر بإنجيل الله قائلا:","1:15":"«قد اكتمل الزمان واقترب ملكوت الله. فتوبوا وآمنوا بالإنجيل! »","1:16":"وفيما كان يسوع يمشي على شاطيء بحيرة الجليل، رأى سمعان وأخاه أندراوس يلقيان الشبكة في البحيرة، فقد كانا صيادين.","1:17":"فقال لهما يسوع: «هيا اتبعاني، فأجعلكما صيادين للناس!»","1:18":"فتركا شباكهما وتبعاه.","1:19":"ثم سار من هناك قليلا، فرأى يعقوب بن زبدي ويوحنا أخاه في القارب يصلحان الشباك،","1:20":"فدعاهما في الحال ليتبعاه، فتركا أباهما زبدي في القارب مع الأجراء، وتبعاه.","1:21":"ثم ذهبوا إلى كفرناحوم. فدخل حالا، في يوم السبت، إلى المجمع وأخذ يعلم.","1:22":"فذهل الحاضرون من تعليمه، لأنه كان يعلمهم كصاحب سلطان وليس كالكتبة.","1:23":"وكان في مجمعهم رجل يسكنه روح نجس، فصر خ","1:24":"وقال: «ما شأنك بنا يايسوع الناصري؟ أجئت لتهلكنا؟ أنا أعرف من أنت. أنت قدوس الله!»","1:25":"فزجره يسوع قائلا: «اخرس واخرج منه!»","1:26":"فطرح الروح النجس الرجل، وصرخ صرخة عالية، وخرج منه.","1:27":"فدهش الجميع حتى أخذوا يتساءلون فيما بينهم: «ما هذا؟ إنه تعليم جديد، يلقى بسلطان، فحتى الأرواح النجسة يأمرها فتطيعه!»","1:28":"وفي الحال انتشر خبر يسوع في كل مكان من المنطقة المجاورة للجليل.","1:29":"وحالما غادروا المجمع، دخلوا بيت سمعان وأندراوس، ومعهم يعقوب ويوحنا.","1:30":"وكانت حماة سمعان طريحة الفراش، تعاني من الحمى. ففي الحال كلموا يسوع بشأنها.","1:31":"فاقترب إليها، وأمسك بيدها وأنهضها. فذهبت عنها الحمى حالا، وقامت تخدمهم.","1:32":"وعند حلول المساء، لما غربت الشمس، أحضر الناس إليه جميع من كانوا مرضى ومسكونين بالشياطين،","1:33":"حتى احتشد أهل المدينة كلهم عند الباب.","1:34":"فشفى كثيرين كانوا يعانون من أمراض مختلفة، وطرد شياطين كثيرة، ولكنه لم يسمح للشياطين بأن يتكلموا، لأنهم عرفوا من هو.","1:35":"وفي اليوم التالي، نهض باكرا قبل الفجر، وخرج إلى مكان مقفر وأخذ يصلي هناك.","1:36":"فذهب سمعان ومن معه يبحثون عنه. فلما وجدوه قالوا له:","1:37":"«إن الجميع يطلبونك!»","1:38":"فقال لهم: «لنذهب إلى مكان آخر في القرى المجاورة لأبشر هناك أيضا. فلأجل هذا جئت","1:39":"وذهب يبشر في مجامع اليهود في منطقة الجليل كلها، ويطرد الشياطين.","1:40":"وجاءه رجل مصاب بالبرص يتوسل إليه. فارتمى على ركبتيه أمامه وقال: «إن أردت، فأنت تقدر أن تطهرني!»","1:41":"فتحنن يسوع ومد يده ولمسه قائلا: «إني أريد، فاطهر!»","1:42":"فحالما تكلم زال البرص عنه وطهر.","1:43":"وفي الحال صرفه يسوع بعدما أنذره بشدة","1:44":"قائلا: «انتبه! لا تخبر أحدا بشيء، بل اذهب واعرض نفسك على الكاهن، وقدم لقاء تطهيرك ما أمر به موسى، فيكون ذلك شهادة لهم!»","1:45":"أما هو، فانطلق ينادي كثيرا ويذيع الخبر، حتى لم يعد يسوع يقدر أن يدخل أية بلدة علنا، بل كان يقيم في أماكن مقفرة، والناس يتوافدون إليه من كل مكان.","2:1":"وبعد بضعة أيام، رجع يسوع إلى بلدة كفرناحوم. وانتشر الخبر أنه في البيت،","2:2":"فاجتمع عدد كبير من الناس، حتى لم يبق مكان لأحد، ولا أمام الباب. فأخذ يلقي عليهم كلمة الله.","2:3":"وجاءه بعضهم بمشلول يحمله أربعة رجال.","2:4":"ولكنهم لم يقدروا أن يقتربوا إليه بسبب الزحام. فنقبوا السقف فوق المكان الذي كان يسوع فيه حتى كشفوه، ثم دلوا الفراش الذي كان المشلول راقدا عليه.","2:5":"فلما رأى يسوع إيمانهم، قال للمشلول: «يابني، قد غفرت لك خطاياك!»","2:6":"وكان بين الجالسين بعض الكتبة، فأخذوا يفكرون في قلوبهم:","2:7":"«لماذا يتكلم هذا الرجل هكذا؟ إنه يجدف! من يقدر أن يغفر الخطايا إلا الله وحده؟»","2:8":"وفي الحال أدرك يسوع بروحه ما يفكرون فيه في قلوبهم، فسألهم: «لماذا تفكرون بهذا الأمر في قلوبكم؟","2:9":"أي الأمرين أسهل أن يقال للمشلول: قد غفرت لك خطاياك، أو أن يقال له: قم احمل فراشك وامش؟","2:10":"ولكني قلت ذلك لتعلموا أن لابن الإنسان على الأرض سلطة غفران الخطايا». ثم قال للمشلول:","2:11":"«لك أقول: قم احمل فراشك، واذهب إلى بيتك!»","2:12":"فقام في الحال، وحمل فراشه، ومشى أمام الجميع. فذهلوا جميعا وعظموا الله قائلين: «ما رأينا مثل هذا قط!»","2:13":"وخرج يسوع ثانية إلى شاطيء البحيرة، فلحق به الجمع كله. فأخذ يعلمهم.","2:14":"وفيما هو سائر، رأى لاوي بن حلفى جالسا في مكتب الجباية، فقال له: «اتبعني!» فقام وتبعه.","2:15":"وبينما كان يسوع متكئا في بيت لاوي، أخذ كثيرون من الجباة والخاطئين يتكئون معه ومع تلاميذه، لأن كثيرين منهم كانوا هناك فلحقوا به.","2:16":"فلما رأى الكتبة والفريسيون يسوع يأكل مع الجباة والخاطئين، قالوا لتلاميذه: «لماذا يأكل مع الجباة والخاطئين؟»","2:17":"فسمع يسوع، وأجاب: «ليس الأصحاء هم المحتاجون إلى الطبيب، بل المرضى. ما جئت لأدعو أبرارا بل خاطئين! »","2:18":"وكان تلاميذ يوحنا والفريسيون صائمين، فجاء بعضهم إلى يسوع يسألونه: «لماذا يصوم تلاميذ يوحنا وتلاميذ الفريسيين، وأما تلاميذك فلا يصومون؟»","2:19":"فأجابهم: «هل يقدر أهل العرس أن يصوموا والعريس بينهم؟ مادام العريس بينهم لا يقدرون أن يصوموا.","2:20":"ولكن ستأتي أيام يكون العريس فيها قد رفع من بينهم. فيومذاك يصومون.","2:21":"لا أحد يرقع ثوبا عتيقا برقعة من قماش جديد وإلا، فإن الرقعة الجديدة تنكمش فتأكل من الثوب العتيق، ويصير الخرق أسوأ!","2:22":"ولا أحد يضع خمرا جديدة في قرب عتيقة، حتى لا تفجر الخمر الجديدة القرب، فتراق الخمر وتتلف القرب. إنما الخمر الجديدة توضع في قرب جديدة».","2:23":"ومر يسوع ذات سبت بين الحقول، فأخذ التلاميذ يشقون طريقهم وهم يقطفون السنابل.","2:24":"فقال الفريسيون ليسوع: «انظر! لماذا يفعل تلاميذك ما لا يحل فعله يوم السبت؟»","2:25":"فأجابهم: «أما قرأتم ما فعله داود ومرافقوه عندما احتاجوا وجاعوا؟","2:26":"كيف دخل بيت الله، في زمان أبيأثار رئيس الكهنة، وأكل خبز التقدمة الذي لا يحل الأكل منه إلا للكهنة وحدهم، بل أعطى مرافقيه أيضا فأكلوا؟»","2:27":"ثم قال لهم: «إنما جعل السبت لفائدة الإنسان، ولم يجعل الإنسان عبدا للسبت.","2:28":"فابن الإنسان هو رب السبت أيضا! »","3:1":"ودخل يسوع المجمع مرة أخرى. وكان هنالك رجل يده يابسة.","3:2":"فأخذوا يراقبونه ليروا هل يشفي ذلك الرجل في السبت، فيتمكنوا من أن يتهموه.","3:3":"فقال للرجل الذي يده يابسة: «قم وقف في الوسط!»","3:4":"ثم سألهم: «هل يحل في السبت فعل الخير أم فعل الشر؟ تخليص نفس أو قتلها؟» فظلوا صامتين.","3:5":"فأدار يسوع نظره فيهم غاضبا وقد تضايق من صلابة قلوبهم، وقال للرجل: «مد يدك!» فمدها، فإذا هي قد عادت صحيحة.","3:6":"وفي الحال خرج الفريسيون من المجمع، ومعهم أعضاء حزب هيرودس، وتآمروا عليه ليقتلوه.","3:7":"فانسحب يسوع وتلاميذه نحو البحيرة. وتبعه جمع كبير من مناطق الجبل واليهودية","3:8":"وأورشليم وأدومية وما وراء الأردن، وجمع كبير من نواحي صور وصيدا، جاءوا إليه إذ كانوا قد سمعوا بما فعل.","3:9":"فأمر يسوع تلاميذه أن يعدوا له قاربا صغيرا يلازمه، لئلا يزحمه الجمع،","3:10":"لأنه كان قد شفى كثيرين، فصار كل من به مرض يسارع إليه ليلمسه.","3:11":"وكانت الأرواح النجسة حين تراه تخر ساجدة له، صارخة: «أنت ابن الله!»","3:12":"فكان يحذرها بشدة من أن تذيع أمره.","3:13":"ثم صعد إلى الجبل، ودعا الذين أرادهم، فأقبلوا إليه.","3:14":"فعين اثني عشر ليلازموه ويرسلهم ليبشروا،","3:15":"وتكون لهم سلطة على طرد الشياطين.","3:16":"والاثنا عشر الذين عينهم، هم: سمعان، وقد سماه بطرس،","3:17":"ويعقوب بن زبدي، ويوحنا أخوه، وقد سماهما بوانرجس، أي ابني الرعد،","3:18":"وأندراوس، وفيلبس، وبرثلماوس، ومتى وتوما، ويعقوب بن حلفى، وتداوس، وسمعان القانوي،","3:19":"ويهوذا الإسخريوطي الذي خانه.","3:20":"ثم رجعوا إلى البيت، فاحتشد الجمع أيضا، ولم يقدر يسوع وتلاميذه حتى على أكل الطعام.","3:21":"فلما سمع أقرباؤه، جاؤا ليأخذوه، إذ كان أشيع أنه فقد صوابه.","3:22":"وأما الكتبة الذين نزلوا من أورشليم، فقالوا: «إن بعلزبول يسكنه، وإنه برئيس الشياطين يطرد الشياطين!»","3:23":"فدعاهم إليه وكلمهم بالأمثال، قال: «كيف يقدر شيطان أن يطرد شيطانا؟","3:24":"فإذا انقسمت مملكة ما على ذاتها، فإنها لا تقدر أن تصمد.","3:25":"وإذا انقسم بيت ما على ذاته، فإنه لا يقدر أن يصمد.","3:26":"فإذا انقلب الشيطان على نفسه وانقسم، فإنه لا يقدر أن يصمد، بل ينتهي أمره!","3:27":"لا يقدر أحد أن يدخل بيت قوي وينهب أمتعته إلا إذا قيد القوي أولا. وبعدئذ ينهب بيته.","3:28":"الحق أقول لكم: إن جميع الخطايا تغفر لبني البشر، حتى التجاديف التي يجدفونها.","3:29":"ولكن من يجدف على الروح القدس، فلا غفران له أبدا، بل إنه يقع تحت عقاب خطيئة أبدية».","3:30":"ذلك لأنهم قالوا: «إن روحا نجسا يسكنه!»","3:31":"وجاء إخوته وأمه، فوقفوا خارج البيت وأرسلوا إليه يدعونه.","3:32":"وكان قد جلس حوله جمع كبير، فقالوا له: «ها إن أمك وإخوتك في الخارج يطلبونك!»","3:33":"فأجابهم: «من أمي وإخوتي؟»","3:34":"ثم أدار نظره في الجالسين حوله وقال: «هؤلاء هم أمي وإخوتي،","3:35":"لأن من يعمل بإرادة الله هو أخي وأختي وأمي! »","4:1":"ثم أخذ يعلم ثانية عند شاطيء البحيرة، وقد احتشد حوله جمع كبير، حتى إنه صعد إلى القارب وجلس فيه فوق الماء، فيما كان الجمع كله على شاطيء البحيرة.","4:2":"فعلمهم أمورا كثيرة بالأمثال. ومما قاله لهم في تعليمه:","4:3":"«اسمعوا! ها إن الزارع قد خرج ليزرع.","4:4":"وبينما هو يزرع، وقع بعض البذار على الممرات، فجاءت الطيور والتهمته.","4:5":"ووقع بعضه على أرض صخرية رقيقة التربة، فنما سريعا لأن تربته لم تكن عميقة.","4:6":"ولكن لما أشرقت الشمس، احتر ق ويبس لأنه كان بلا أصل.","4:7":"ووقع بعض البذار بين الأشواك، فنبت الشوك وخنقه، فلم يثمر.","4:8":"وبعض البذار وقع في الأرض الجيدة، فنبت ونما وأثمر، فأعطى بعضه ثلاثين ضعفا، وبعضه ستين، وبعضه مئة».","4:9":"ثم قال: «من له أذنان للسمع، فليسمع! »","4:10":"وعندما كان يسوع وحده، سأله الذين حوله والاثنا عشر عن مغزى المثل.","4:11":"فقال لهم: «قد أعطي لكم أن تعرفوا سر ملكوت الله. أما الذين من خارج، فكل شيء يقدم لهم بالأمثال،","4:12":"حتى إنهم: نظرا ينظرون ولا يبصرون، وسمعا يسمعون ولا يفهمون، لئلا يتوبوا فتغفر لهم خطاياهم! »","4:13":"وقال لهم: «ألم تفهموا هذا المثل؟ فكيف تفهمون جميع الأمثال الأخرى؟","4:14":"إن الزارع يزرع كلمة الله.","4:15":"وهؤلاء الذين على الممرات حيث تزرع الكلمة، هم الذين حالما يسمعون يأتي الشيطان ويخطف الكلمة التي زرعت فيهم.","4:16":"وكذلك هؤلاء الذين تزرع فيهم الكلمة على أرض صخرية، وهم الذين حالما يسمعون الكلمة يقبلونها بفرح،","4:17":"ولا أصل لهم في ذواتهم، وإنما هم إلى حين. فحالما يحدث ضيق أو اضطهاد من أجل الكلمة، يتعثرون.","4:18":"والآخرون الذين تزرع فيهم الكلمة بين الأشواك، هؤلاء هم الذين قد سمعوا الكلمة،","4:19":"ولكن هموم الزمان الحاضر وخداع الغنى واشتهاء الأمور الأخرى، تدخل إليهم وتخنق الكلمة، فتصير بلا ثمر.","4:20":"وأما الذين تزرع فيهم الكلمة في الأرض الجيدة، فهؤلاء هم الذين يسمعون الكلمة ويقبلونها فيثمرون، بعضهم ثلاثين ضعفا وبعضهم ستين، وبعضهم مئة».","4:21":"وقال لهم: «هل يؤتى بالمصباح ليوضع تحت المكيال أو تحت السرير؟ أليس ليوضع على المنارة؟","4:22":"فليس من محجوب إلا سيكشف، وما كتم شيء إلا ليعلن!","4:23":"من له أذنان للسمع، فليسمع! »","4:24":"وقال لهم: «تنبهوا لما تسمعون. فبأي كيل تكيلون، يكال لكم ويزاد لكم.","4:25":"فإن من عنده يعطى المزيد، ومن ليس عنده، فحتى الذي عنده ينتزع منه».","4:26":"وقال: «إن ملكوت الله يشبه بإنسان يلقي البذار على الأرض،","4:27":"ثم ينام ليلا ويقوم نهارا فيما البذار يطلع وينمو، وهو لا يدري كيف يحدث الأمر.","4:28":"فالأرض من ذاتها تعطي الثمر، فتطلع أولا عشبة، ثم سنبلة، ثم قمحا ملء السنبلة.","4:29":"ولكن حالما ينضج الثمر، يعمل فيه المنجل إذ يكون الحصاد قد حان».","4:30":"وقال: «بماذا نشبه ملكوت الله، وبأي مثل نمثله؟","4:31":"إنه يشبه ببزرة خردل، تكون عند بذرها على الأرض أصغر من كل ما على الأرض من بزور،","4:32":"ولكن متى تم زرعها، تطلع أغصانا كبيرة، حتى إن طيور السماء تستطيع أن تبيت في ظلها».","4:33":"بكثير من مثل هذه الأمثال كان يسوع يكلم الجمع بالكلمة، على قدر ما كانوا يطيقون أن يسمعوا.","4:34":"وبغير مثل لم يكن يكلمهم. ولكنه كان يفسر لتلاميذه كل شيء حين ينفرد بهم.","4:35":"وفي ذلك اليوم، عندما حل المساء، قال لتلاميذه: «لنعبر إلى الضفة المقابلة!»","4:36":"فلما صرفوا الجمع، أخذوه معهم في القارب الذي كان فيه. وكان معه أيضا قوارب أخرى.","4:37":"فهبت عاصفة ريح شديدة، وأخذت الأمواج تضرب القارب حتى كاد يمتلىء ماء.","4:38":"وكان هو في مؤخر القارب نائما على وسادة. فأيقظوه وقالوا له: «يامعلم، أما يهمك أننا نهلك؟»","4:39":"فنهض، وزجر الريح، وقال للبحر: «اصمت. اخرس!» فسكنت الريح وساد هدوء تام.","4:40":"ثم قال لهم: «لماذا أنتم خائفون هكذا؟ كيف لا إيمان لكم؟»","4:41":"فخافوا خوفا شديدا، وقال بعضهم لبعض: «من هو هذا، حتى إن الريح والبحر يطيعانه؟ »*","5:1":"ثم وصلوا إلى الضفة المقابلة من البحيرة، إلى بلدة الجراسيين.","5:2":"وحالما نزل من القارب، لاقاه من بين القبور إنسان يسكنه روح نجس،","5:3":"كان يقيم في القبور. ولم يكن أحد يقدر أن يقيده ولو بالسلاسل.","5:4":"فإنه كثيرا ما ربط بالقيود والسلاسل، فكان يقطع السلاسل ويحطم القيود، ولم يقدر أحد أن يخضعه.","5:5":"وكان في القبور وفي الجبال دائما، ليلا ونهارا، يصيح ويجرح جسمه بالحجارة.","5:6":"ولكنه لما رأى يسوع من بعيد، ركض وسجد له،","5:7":"وصرخ بأعلى صوته: «ما شأنك بي يايسوع ابن الله العلي؟ أستحلفك بالله ألا تعذبني!»","5:8":"فإن يسوع كان قد قال له؟ «أيها الروح النجس، اخرج من الإنسان!»","5:9":"وسأله يسوع: «ما اسمك؟» فأجاب: «اسمي لجيون لأننا جيش كبير!»","5:10":"وتوسل إليه بإلحاح ألا يطرد الأرواح النجسة إلى خارج تلك المنطقة.","5:11":"وكان هناك قطيع كبير من الخنازير يرعى عند الجبل،","5:12":"فتوسلت الأرواح النجسة إلى يسوع قائلة: «أرسلنا إلى الخنازير لندخل فيها!»","5:13":"فأذن لها بذلك. فخرجت الأرواح النجسة ودخلت في الخنازير، فاندفع قطيع الخنازير من على حافة الجبل إلى البحيرة، فغرق فيها. وكان عدده نحو ألفين.","5:14":"أما رعاة الخنازير فهربوا وأذاعوا الخبر في المدينة وفي المزارع. فخرج الناس ليروا ما قد جرى،","5:15":"وجاءوا إلى يسوع، فرأوا الذي كان مسكونا بالشياطين جالسا ولابسا وصحيح العقل، فاستولى عليهم الخوف.","5:16":"فحدثهم الذين رأوا ما جرى بما حدث للمجنون وللخنازير","5:17":"فأخذوا يرجون من يسوع أن يرحل عن ديارهم.","5:18":"وفيما كان يركب القارب، توسل إليه الإنسان الذي كانت الشياطين تسكنه أن يرافقه.","5:19":"فلم يسمح له، بل قال له: «اذهب إلى بيتك، وإلى أهلك، وأخبرهم بما عمله الرب بك ورحمك».","5:20":"فانطلق وأخذ ينادي في المدن العشر بما عمله يسوع به. فتعجب الجميع.","5:21":"ولما عاد يسوع وعبر في القارب إلى الضفة المقابلة من البحيرة، اجتمع إليه وهو عند الشاطيء جمع كبير.","5:22":"وإذا واحد من رؤساء المجمع، واسمه يايرس، قد جاء إليه. وما إن رآه، حتى ارتمى عند قدميه،","5:23":"وتوسل إليه بإلحاح، قائلا: «ابنتي الصغيرة مشرفة على الموت. فتعال والمسها بيدك لتشفى فتحيا!»","5:24":"فذهب معه، يتبعه جمع كبير وهم يزحمونه.","5:25":"وكانت هناك امرأة مصابة بنزيف دموي منذ اثنتي عشرة سنة،","5:26":"وقد عانت الكثير من الألم على أيدي أطباء كثيرين، وأنفقت في سبيل علاجها كل ما تملك، فلم تجن أية فائدة، بل بالأحرى ازدادت حالتها سوءا.","5:27":"فإذ كانت قد سمعت عن يسوع، جاءت في زحمة الجمع من خلفه ولمست رداءه،","5:28":"لأنها قالت: «يكفي أن ألمس ثيابه لأشفى».","5:29":"وفي الحال انقطع نزيف دمها وأحست في جسمها أنها شفيت من علتها.","5:30":"وحالما شعر يسوع في نفسه بالقوة التي خرجت منه، أدار نظره في الجمع وسأل: «من لمس ثيابي؟»","5:31":"فقال له تلاميذه: «أنت ترى الجمع يزحمونك، وتسأل: من لمسني؟»","5:32":"ولكنه ظل يتطلع حوله ليرى التي فعلت ذلك.","5:33":"فما كان من المرأة، وقد علمت بما حدث لها، إلا أن جاءت وهي خائفة ترتجف، وارتمت أمامه وأخبرته بالحقيقة كلها.","5:34":"فقال لها: «ياابنة، إيمانك قد شفاك. فاذهبي بسلام وتعافي من علتك !»","5:35":"وبينما يسوع يتكلم، جاء بعضهم من بيت رئيس المجمع قائلين: «ابنتك قد ماتت. فلماذا تكلف المعلم بعد؟»","5:36":"ولكن يسوع، ما إن سمع بذلك الخبر، حتى قال لرئيس المجمع: «لا تخف؛ آمن فقط!»","5:37":"ولم يدع أحدا يرافقه إلا بطرس ويعقوب ويوحنا أخا يعقوب.","5:38":"ووصل إلى بيت رئيس المجمع، فرأى الجلبة والناس يبكون ويولولون كثيرا.","5:39":"فلما دخل، قال لهم: «لماذا تضجون وتبكون؟ لم تمت الصبية، بل هي نائمة».","5:40":"فضحكوا منه. أما هو، فأخرجهم جميعا، ثم أخذ معه أبا الصبية وأمها والذين كانوا يرافقونه، ودخل حيث كانت الصبية.","5:41":"وإذ أمسك بيدها قال: «طليثا قومي!» أي: «ياصبية، لك أقول: قومي».","5:42":"فنهضت الصبية حالا وأخذت تمشي، إذ كان عمرها اثنتي عشر ة سنة. فدهش الجميع دهشة عظيمة.","5:43":"فأمرهم بشدة أن لا يعلم أحد بذلك، وطلب أن تعطى ما تأكله.","6:1":"وغادر يسوع ذلك المكان وعاد إلى بلدته، وتلاميذه يتبعونه.","6:2":"ولما حل السبت، أخذ يعلم في المجمع، فدهش كثيرون حين سمعوه، وقالوا: «من أين له هذا؟ وما هذه الحكمة الموهوبة له، وهذه المعجزات الجارية على يديه؟","6:3":"أليس هذا هو النجار ابن مريم، وأخا يعقوب ويوسي ويهوذا وسمعان؟ أوليست أخواته عندنا هنا؟» هكذا كانوا يشكون فيه.","6:4":"ولكن يسوع قال لهم: «لا يكون النبي بلا كرامة إلا في بلدته، وبين أقربائه، وفي بيته!»","6:5":"ولم يقدر أن يعمل هناك أية معجزة، غير أنه لمس بيديه عددا قليلا من المرضى فشفاهم.","6:6":"وتعجب من عدم إيمانهم. ثم أخذ يطوف بالقرى المجاورة وهو يعلم.","6:7":"ثم استدعى الاثني عشر تلميذا، وأخذ يرسلهم اثنين اثنين، وقد أعطاهم سلطة على الأرواح النجسة،","6:8":"وأوصاهم أن لا يحملوا للطريق شيئا إلا عصا، لا خبزا ولا زادا ولا مالا ضمن أحزمتهم،","6:9":"بل ينتعلوا حذاء ويلبسوا رداء واحدا.","6:10":"وقال لهم: «أينما دخلتم بيتا، فأقيموا فيه إلى أن ترحلوا من هناك.","6:11":"وإن كان أحد لا يقبلكم ولا يسمع لكم في مكان ما، فاخرجوا من هناك، وانفضوا التراب عن أقدامكم شهادة عليهم».","6:12":"فانطلقوا يبشرون داعين إلى التوبة،","6:13":"وطردوا شياطين كثيرة، ودهنوا كثيرين من المرضى بزيت، وشفوهم.","6:14":"وسمع الملك هيرودس عن يسوع، لأن اسمه كان قد صار مشهورا، إذ قال بعضهم: «هذا يوحنا المعمدان وقد قام من بين الأموات، ولذلك تجرى على يده المعجزات!»","6:15":"وآخرون قالوا: «هذا إيليا» وغيرهم قالوا: «هذا نبي كباقي الأنبياء!»","6:16":"وأما هيرودس، فلما سمع قال «ما هو إلا يوحنا الذي قطعت أنا رأسه، وقد قام! »","6:17":"فإن هيرودس هذا كان قد أرسل وقبض على يوحنا وقيده في السجن. وذلك من أجل هيروديا التي تزوجها هيرودس وهي زوجة أخيه فيلبس.","6:18":"فإن يوحنا كان يقول له: «ليس حلالا لك أن تتزوج بزوجة أخيك!»","6:19":"فكانت هيروديا ناقمة على يوحنا، وتتمنى أن تقتله، ولكنها لم تستطع.","6:20":"فقد كان هيرودس يرهب يوحنا لعلمه أنه رجل بار وقديس، وكان يحافظ على سلامته. ومع أنه كان يتضايق كثيرا من كلامه، إلا أنه كان يحب الاستماع إليه.","6:21":"ثم سنحت الفرصة عندما أقام هيرودس بمناسبة ذكرى مولده وليمة لعظمائه وقادة الألوف وأعيان منطقة الجليل.","6:22":"فقد دخلت ابنة هيروديا ورقصت، فسرت هيرودس والمتكئين معه. فقال الملك للصبية: «اطلبي مني ما تريدين، فأعطيك إياه!»","6:23":"وأقسم لها قائلا: «لأعطينك مهما طلبت مني، ولو نصف مملكتي!»","6:24":"فخرجت وسألت أمها: «ماذا أطلب؟» فأجابت: «رأس يوحنا المعمدان!»","6:25":"فعادت في الحال إلى الداخل وطلبت من الملك قائلة: «أريد أن تعطيني حالا رأس يوحنا المعمدان على طبق!»","6:26":"فحزن الملك جدا. ولكنه لأجل ما أقسم به ولأجل المتكئين معه، لم يرد أن يخلف وعده لها.","6:27":"وفي الحال أرسل الملك سيافا وأمر أن يؤتى برأس يوحنا. فذهب السياف وقطع رأس يوحنا في السجن،","6:28":"ثم جاء بالرأس على طبق وقدمه إلى الصبية فحملته إلى أمها.","6:29":"ولما سمع تلاميذ يوحنا بذلك، جاءوا ورفعوا جثمانه، ودفنوه في قبر.","6:30":"واجتمع الرسل إلى يسوع، وأخبروه بكل شيء: بما عملوه وما علموه.","6:31":"فقال لهم: «تعالوا أنتم على انفراد إلى مكان خال، واستريحوا قليلا». فقد كان القادمون والذاهبون كثيرين حتى لم يدعوا لهم فرصة للأكل.","6:32":"فذهب التلاميذ في القارب إلى مكان مقفر منفردين.","6:33":"ولكن كثيرين رأوهم منطلقين، فعرفوا وجهتهم، وأخذوا يتراكضون معا إلى هناك سيرا على الأقدام، خارجين من جميع المدن، فسبقوهم.","6:34":"فلما نزل يسوع من القارب، رأى الجمع الكثير وتحنن عليهم، لأنهم كانوا كغنم لا راعي لها. فأخذ يعلمهم أمورا كثيرة.","6:35":"ولما مضى جزء كبير من النهار، تقدم إليه تلاميذه، وقالوا: «المكان مقفر، والنهار كاد ينقضي.","6:36":"فاصرف الجمع ليذهبوا إلى القرى والمزارع المجاورة ويشتروا لأنفسهم ما يأكلون».","6:37":"فرد قائلا: «أعطوهم أنتم ليأكلوا!» فقالوا له: «هل نذهب ونشتري بمئتي دينار خبزا ونعطيهم ليأكلوا؟»","6:38":"فسألهم: «كم رغيفا عندكم؟ اذهبوا وانظروا». فلما تحققوا، قالوا: «خمسة، وسمكتان!»","6:39":"فأمرهم أن يجلسوا الجمع جماعات جماعات على العشب الأخضر.","6:40":"فجلسوا في حلقات تتألف كل منها من مئة أو خمسين.","6:41":"ثم أخذ يسوع الأرغفة الخمسة والسمكتين، ورفع نظره إلى السماء وبارك، وكسر الأرغفة، وأعطى تلاميذه ليقدموا للجمع والسمكتان قسمهما للجميع.","6:42":"فأكلوا جميعا وشبعوا.","6:43":"ثم رفعوا اثنتي عشرة قفة مملوءة من كسر الخبز وبقايا السمك.","6:44":"وأما الذين أكلوا من الخبز، فكانوا خمسة آلاف رجل.","6:45":"وفي الحال ألزم تلاميذه أن يركبوا القارب ويسبقوه إلى الضفة المقابلة، إلى بيت صيدا، ريثما يصرف الجمع.","6:46":"وبعدما صرفهم ذهب إلى الجبل ليصلي.","6:47":"ولما حل المساء، كان القارب في وسط البحيرة، ويسوع وحده على البر.","6:48":"وإذ رآهم يتعذبون في التجذيف، لأن الريح كانت معاكسة لهم، جاء إليهم ماشيا على ماء البحيرة، نحو الربع الأخير من الليل، وكاد أن يتجاوزهم.","6:49":"ولكنهم لما رأوه ماشيا على الماء، ظنوه شبحا فصرخوا.","6:50":"فقد رأوه كلهم وذعروا. إلا أنه كلمهم في الحال وقال لهم: «تشجعوا، أنا هو، لا تخافوا!»","6:51":"وصعد إليهم في القارب فسكنت الريح. فدهشوا دهشة فائقة، وتعجبوا جدا،","6:52":"لأنهم لم يفهموا بمعجزة الأرغفة، فقد كانت قلوبهم قاسية.","6:53":"ولما عبروا إلى الضفة المقابلة، جاءوا إلى أرض جنيسارت، وأرسوا القارب.","6:54":"وحالما نزلوا من القارب، عرفه الناس،","6:55":"فطافوا في أنحاء تلك البلاد المجاورة، وأخذوا يحملون من كانوا مرضى على فرش إلى كل مكان يسمعون أنه فيه.","6:56":"وأينما دخل، إلى القرى أو المدن أو المزارع، وضعوا المرضى في الساحات العامة، متوسلين إليه أن يلمسوا ولو طرف ردائه. فكان كل من يلمسه يشفى.","7:1":"واجتمع إليه الفريسيون وبعض الكتبة، قادمين من أورشليم.","7:2":"ورأوا بعض تلاميذه يتناولون الطعام بأيد نجسة، أي غير مغسولة.","7:3":"فقد كان الفريسيون، واليهود عامة، لا يأكلون ما لم يغسلوا أيديهم مرارا، متمسكين بتقليد الشيوخ.","7:4":"وإذا عادوا من السوق، لا يأكلون ما لم يغتسلوا. وهناك طقوس أخرى كثيرة تسلموها ليتمسكوا بها، كغسل الكؤوس والأباريق وأوعية النحاس.","7:5":"عندئذ سأله الفريسيون والكتبة: «لماذا لا يسلك تلاميذك وفقا لتقليد الشيوخ، بل يتناولون الطعام بأيد نجسة؟»","7:6":"فرد عليهم قائلا: «أحسن إشعياء إذ تنبأ عنكم أيها المراؤون، كما جاء في الكتاب: هذا الشعب يكرمني بشفتيه، وأما قلبه فبعيد عني جدا.","7:7":"إنما باطلا يعبدونني وهم يعلمون تعاليم ليست إلا وصايا الناس !","7:8":"فقد أهملتم وصية الله وتمسكتم بتقليد الناس!»","7:9":"وقال لهم: «حقا أنكم رفضتم وصية الله لتحافظوا على تقليدكم أنتم!","7:10":"فإن موسى قال: أكرم أباك وأمك! وأيضا: من أهان أباه أو أمه، فليكن الموت عقابا له!","7:11":"ولكنكم أنتم تقولون: إذا قال أحد لأبيه أو أمه: إن ما كنت أعولك به قد جعلته قربانا، أي تقدمة (للهيكل)،","7:12":"فهو في حل من إعانة أبيه أو أمه!","7:13":"وهكذا تبطلون كلمة الله بتعليمكم التقليدي الذي تتناقلونه. وهناك أمور كثيرة مثل هذه تفعلونها! »","7:14":"وإذ دعا الجمع إليه ثانية، قال لهم: «اسمعوا لي كلكم وافهموا!","7:15":"لا شيء من خارج الإنسان إذا دخله يمكن أن ينجسه. أما الأشياء الخارجة من الإنسان، فهي التي تنجسه.","7:16":"من له أذنان للسمع، فليسمع».","7:17":"ولما غادر الجمع ودخل البيت، استفسره التلاميذ مغزى المثل،","7:18":"فقال لهم: «أهكذا أنتم أيضا لا تفهمون؟ ألا تدركون أن كل ما يدخل الإنسان من الخارج لا يمكن أن ينجسه،","7:19":"لأنه لا يدخل إلى قلبه بل إلى البطن، ثم يخرج إلى الخلاء؟» مما يجعل الأطعمة كلها طاهرة.","7:20":"ثم قال: «إن الذي يخرج من الإنسان، هو ينجس الإنسان.","7:21":"فإنه من الداخل، من قلوب الناس، تنبع الأفكار الشريرة، الفسق، السرقة، القتل،","7:22":"الزنى، الطمع، الخبث، الخداع، العهارة، العين الشريرة، التجديف، الكبرياء، الحماقة","7:23":"هذه الأمور الشريرة كلها تنبع من داخل الإنسان وتنجسه».","7:24":"ثم ترك يسوع تلك المنطقة وذهب إلى نواحي صور. فدخل بيتا وهو لا يريد أن يعلم به أحد. ومع ذلك، لم يستطع أن يظل مختفيا.","7:25":"فإن امرأة كان بابنتها روح نجس، ما إن سمعت بخبره حتى جاءت وارتمت على قدميه،","7:26":"وكانت المرأة يونانية، من أصل سوري فينيقي، وتوسلت إليه أن يطرد الشيطان من ابنتها.","7:27":"ولكنه قال لها: «دعي البنين أولا يشبعون! فليس من الصواب أن يؤخذ خبز البنين ويطرح للكلاب».","7:28":"فأجابت قائلة له: «صحيح ياسيد! ولكن الكلاب تحت المائدة تأكل من فتات البنين!»","7:29":"فقال لها: «لأجل هذه الكلمة اذهبي، فقد خرج الشيطان من ابنتك!»","7:30":"فلما رجعت إلى بيتها، وجدت ابنتها على السرير وقد خرج منها الشيطان.","7:31":"ثم غادر يسوع نواحي صور وعاد إلى بحيرة الجليل، مرورا بصيدا وعبر حدود المدن العشر.","7:32":"فأحضروا إليه أصم معقود اللسان، وتوسلوا إليه أن يضع يده عليه.","7:33":"فانفرد به بعيدا عن الجمع. ووضع إصبعيه في أذني الرجل، ثم تفل ولمس لسانه،","7:34":"ورفع نظره إلى السماء، وتنهد وقال له: «افتح!» أي انفتح.","7:35":"وفي الحال انفتحت أذناه وانحلت عقدة لسانه، وتكلم بطلاقة.","7:36":"وأوصاهم أن لا يخبروا أحدا بذلك. ولكن كلما أوصاهم أكثر، كانوا يكثرون من إعلان الخبر.","7:37":"وذهلوا إلى الغاية، قائلين: «إنه يبدع في كل ما يفعل. فهو يجعل الصم يسمعون والخرس يتكلمون».","8:1":"في تلك الأيام، إذ احتشد أيضا جمع كبير، ولم يكن عندهم ما يأكلون، دعا يسوع تلاميذه إليه وقال لهم:","8:2":"«إني أشفق على الجمع لأنهم ما زالوا معي منذ ثلاثة أيام، وليس عندهم ما يأكلون.","8:3":"وإن صرفتهم إلى بيوتهم صائمين، تخور قواهم في الطريق، لأن بعضا منهم جاءوا من أماكن بعيدة».","8:4":"فقال له التلاميذ: «من أين يستطيع أحد أن يشبع هؤلاء خبزا هنا في هذا المكان المقفر؟»","8:5":"فسألهم: «كم رغيفا عندكم؟» أجابوا: «سبعة!»","8:6":"فأمر الجمع أن يجلسوا على الأرض. ثم أخذ الأرغفة السبعة، وشكر، وأعطى تلاميذه ليقدموا للجمع، ففعلوا","8:7":"وكان معهم أيضا بعض سمكات صغار، فباركها وأمر بتقديمها أيضا إلى الجمع.","8:8":"فأكل الجميع حتى شبعوا. ثم رفع التلاميذ سبعة سلال ملأوها بما فضل من الكسر.","8:9":"وكان الآكلون نحو أربعة آلاف. ثم صرفهم،","8:10":"وفي الحال ركب القارب مع تلاميذه، وجاء إلى نواحي دلمانوثة.","8:11":"فأقبل الفريسيون وأخذوا يجادلونه، طالبين منه آية من السماء ليجربوه.","8:12":"فتنهد متضايقا، وقال: «لماذا يطلب هذا الجيل آية؟ الحق أقول لكم: لن يعطى هذا الجيل آية! »","8:13":"ثم تركهم وعاد فركب القارب وعبر إلى الضفة المقابلة.","8:14":"وكانوا قد نسوا أن يتزودوا خبزا، ولم يكن معهم في القارب إلا رغيف واحد.","8:15":"وأوصاهم قائلا: «انتبهوا! خذوا حذركم من خمير الفريسيين وخمير هيرودس».","8:16":"فأخذوا يحاجون بعضهم بعضا، قائلين: «ذلك لأنه ليس عندنا خبز».","8:17":"فعلم يسوع بذلك، وقال لهم: «لماذا يحاج بعضكم بعضا لأنه ليس عندكم خبز؟ ألا تدركون بعد ولا تفهمون؟ أما زالت قلوبكم متقسية؟","8:18":"لكم عيون، ألا تبصرون؟ لكم آذان، ألا تسمعون؟ أولستم تذكرون؟","8:19":"عندما كسرت الأرغفة الخمسة للخمسة الآلاف، كم قفة ملأى بالكسر رفعتم؟» قالوا له: «اثنتي عشرة!»","8:20":"«وعندما كسرت الأرغفة السبعة للأربعة الآلاف، كم سلا مليئا بالكسر رفعتم؟» قالوا: «سبعة!»","8:21":"فقال لهم: «وكيف لا تفهمون بعد؟ »","8:22":"وجاءوا إلى بلدة بيت صيدا، فأحضر بعضهم إليه أعمى وتوسلوا إليه أن يضع يده عليه.","8:23":"فأمسك بيد الأعمى واقتاده إلى خارج القرية، وبعدما تفل على عينيه، وضع يديه عليه وسأله: «هل ترى شيئا؟»","8:24":"فتطلع، وقال: «أرى أناسا، كأنهم أشجار، يمشون».","8:25":"فوضع يديه ثانية على عينيه، فتطلع بانتباه، وعاد صحيحا يرى كل شيء واضحا.","8:26":"فأرسله إلى بيته قائلا: «لا تدخل ولا إلى القرية! »","8:27":"ثم توجه يسوع وتلاميذه إلى قرى قيصرية فيلبس. وفي الطريق، سأل تلاميذه: «من يقول الناس إني أنا؟»","8:28":"فأجابوه: «(يقول بعضهم) إنك يوحنا المعمدان، وغيرهم إنك إيليا، وآخرون إنك واحد من الأنبياء».","8:29":"فسألهم: «وأنتم، من تقولون إني أنا؟» فأجابه بطرس: «أنت المسيح!»","8:30":"فحذرهم من أن يخبروا أحدا بأمره.","8:31":"وأخذ يعلمهم أن ابن الإنسان لابد أن يتألم كثيرا، ويرفضه الشيوخ ورؤساء الكهنة والكتبة، ويقتل، وبعد ثلاثة أيام يقوم.","8:32":"وقد تحدث عن هذا الأمر صراحة. فانتحى به بطرس جانبا وأخذ يوبخه.","8:33":"ولكنه التفت ونظر إلى تلاميذه وزجر بطرس قائلا: «اغرب من أمامي ياشيطان، لأنك تفكر لا بأمور الله بل بأمور الناس! »","8:34":"ثم دعا الجمع مع تلاميذه، وقال لهم: «إن أراد أحد أن يسير ورائي، فلينكر نفسه، ويحمل صليبه، ويتبعني.","8:35":"فأي من أراد أن يخلص نفسه، يخسرها. ولكن من يخسر نفسه من أجلي ومن أجل الإنجيل، فهو يخلصها.","8:36":"فماذا ينتفع الإنسان لو ربح العالم كله وخسر نفسه؟","8:37":"أو ماذا يقدم الإنسان فداء عن نفسه؟","8:38":"فإن أي من يستحي بي وبكلامي في هذا الجيل الفاسق الخاطيء، به يستحي ابن الإنسان عندما يعود في مجد أبيه مع الملائكة المقدسين».","9:1":"وقال لهم: «الحق أقول لكم: إن بعضا من الواقفين هنا، لن يذوقوا الموت إلا بعد أن يروا ملكوت الله وقد أتى بقدرة. »","9:2":"وبعد ستة أيام، أخذ يسوع بطرس ويعقوب ويوحنا وحدهم، وصعد بهم على انفراد إلى جبل عال، حيث تجلى أمامهم،","9:3":"وصارت ثيابه لماعة تفوق الثلج بياضا، يعجز أي قصار على الأرض أن يبيض ما يماثلها.","9:4":"وظهر لهم إيليا وموسى يتحدثان مع يسوع.","9:5":"فبدأ بطرس يقول ليسوع: «ياسيد، ما أحسن أن نبقى هنا. فلننصب ثلاث خيام: واحدة لك، وواحدة لموسى، وواحدة لإيليا!»","9:6":"فإنه لم يكن يدري ما يقول، إذ كان الخوف قد استولى عليهم.","9:7":"وجاءت سحابة فخيمت عليهم، وانطلق صوت من السحابة يقول: «هذا هو ابني الحبيب. له اسمعوا!»","9:8":"وفجأة نظروا حولهم فلم يروا أحدا معهم إلا يسوع وحده.","9:9":"وفيما هم نازلون من الجبل، أوصاهم ألا يخبروا أحدا بما رأوا، إلا بعد أن يكون ابن الإنسان قد قام من بين الأموات.","9:10":"فعملوا بهذه الوصية، متسائلين فيما بينهم «ماذا يعني بالقيامة من بين الأموات؟»","9:11":"وسألوه: «لماذا يقول الكتبة إن إيليا لابد أن يأتي قبلا؟»","9:12":"فأجابهم: «حقا، إن إيليا يأتي قبلا ويصلح كل شيء. كذلك جاء في الكتاب أن ابن الإنسان لابد أن يتألم كثيرا ويهان.","9:13":"على أني أقول لكم: إن إيليا قد أتى فعلا، وقد عملوا به أيضا كل ما شاءوا، كما جاء عنه في الكتاب! »","9:14":"ولما وصلوا إلى باقي التلاميذ، رأوا جمعا عظيما حولهم وبعض الكتبة يجادلونهم.","9:15":"وحالما رآه الجمع، ذهلوا كلهم وأسرعوا إليه يسلمون عليه.","9:16":"فسألهم: «فيم تجادلونهم؟»","9:17":"فرد عليه واحد من الجمع قائلا: «يامعلم، أحضرت إليك ابني وبه روح أخرس،","9:18":"حيثما تملكه يصرعه، فيزبد ويصر بأسنانه ويتيبس. وقد طلبت من تلاميذك أن يطردوه، فلم يقدروا».","9:19":"فأجابهم قائلا: «أيها الجيل غير المؤمن! إلى متى أبقى معكم؟ إلى متى أحتملكم؟ أحضروه إلي!»","9:20":"فأحضروه إلى يسوع. فما إن رآه الروح، حتى صرع الصبي، فوقع على الأرض يتمرغ مزبدا.","9:21":"وسأل أباه: «منذ متى يصيبه هذا؟» فأجاب: «منذ طفولته.","9:22":"وكثيرا ما ألقاه في النار وفي الماء ليهلكه. ولكن إن كنت تقدر على شيء، فأشفق علينا وأعنا!»","9:23":"فقال له يسوع: «بل إن كنت أنت تقدر أن تؤمن، فكل شيء مستطاع لدى المؤمن!»","9:24":"فصرخ أبو الصبي في الحال: «أنا أومن، فأعن عدم إيماني».","9:25":"فلما رأى يسوع الجمع يركضون معا، زجر الروح النجس قائلا له: «أيها الروح الأخرس الأصم، إني آمرك، فاخرج منه ولا تعد تدخله بعد!»","9:26":"فصرخ الروح وصرع الصبي بشدة، ثم خرج. وصار الصبي كأنه ميت، حتى قال أكثر الجمع: «إنه مات!»","9:27":"ولكن لما أمسكه يسوع بيده وأنهضه، نهض.","9:28":"وبعدما دخل يسوع البيت، سأله تلاميذه على انفراد: «لماذا لم نقدر نحن أن نطرد الروح؟»","9:29":"فأجاب: «هذا النوع لا يطرد بشيء إلا بالصلاة والصوم! »","9:30":"ثم انصرفوا من هناك واجتازوا منطقة الجليل، ولم يرد أن يعلم به أحد،","9:31":"لأنه كان يعلم تلاميذه فيقول لهم: «إن ابن الإنسان سيسلم إلى أيدي الناس، فيقتلونه، وبعد قتله يقوم في اليوم الثالث».","9:32":"ولكنهم لم يفهموا هذا القول، وخافوا أن يسألوه.","9:33":"ثم جاء إلى كفرناحوم. وبينما هو في البيت، سأل تلاميذه: «فيم كنتم تتجادلون في الطريق؟».","9:34":"فسكتوا، إذ كانوا في الطريق قد تجادلوا في من هو الأعظم بينهم.","9:35":"فجلس، ودعا الاثني عشر تلميذا، وقال لهم: «إن أراد أحد أن يكون الأول، فليجعل نفسه آخر الجميع وخادما للجميع!»","9:36":"ثم أخذ ولدا صغيرا وأوقفه في وسطهم، وضمه بذراعيه، وقال لهم:","9:37":"«أي من قبل باسمي واحدا مثل هذا من الأولاد الصغار، فقد قبلني. ومن قبلني، فلا يقبلني أنا، بل ذاك الذي أرسلني».","9:38":"فتكلم يوحنا قائلا: «يامعلم، رأينا واحدا يطرد شياطين باسمك، وهو لا يتبعنا، فمنعناه لأنه لا يتبعنا!»","9:39":"فقال يسوع: «لا تمنعوه! فما من أحد يعمل معجزة باسمي ويمكنه أن يتكلم علي بالسوء سريعا بعد ذلك.","9:40":"فإن من ليس ضدنا فهو معنا.","9:41":"فإن من سقاكم كأس ماء باسمي لأنكم خاصة المسيح، فالحق أقول لكم إن مكافأته لن تضيع!","9:42":"ومن كان عثرة لأحد الصغار المؤمنين بي، فأفضل له لو علق في عنقه حجر الرحى وطرح في البحر.","9:43":"فإن كانت يدك فخا لك، فاقطعها: أفضل لك أن تدخل الحياة ويدك مقطوعة من أن تكون لك يدان وتذهب إلى جهنم، إلى النار التي لا تطفأ","9:44":"حيث دودهم لا يموت، والنار لا تطفأ","9:45":"وإن كانت رجلك فخا لك، فاقطعها: أفضل لك أن تدخل الحياة ورجلك مقطوعة من أن تكون لك رجلان وتطرح في جهنم، في النار التي لا تطفأ.","9:46":"حيث دودهم لا يموت، والنار لا تطفأ.","9:47":"وإن كانت عينك فخا لك، فاقلعها: أفضل لك أن تدخل ملكوت الله وعينك مقلوعة من أن تكون لك عينان وتطرح في جهنم النار.","9:48":"حيث دودهم لا يموت، والنار لا تطفأ.","9:49":"فإن كل واحد سوف تملحه النار.","9:50":"الملح جيد، ولكن إذا فقد الملح ملوحته، فبماذا تعيدون إليه طعمه؟ فليكن لكم ملح في أنفسكم، وكونوا مسالمين بعضكم لبعض! »","10:1":"ثم غادر تلك المنطقة وجاء إلى نواحي منطقة اليهودية وما وراء الأردن. فاجتمعت إليه الجموع ثانية وأخذ يعلمهم كعادته.","10:2":"وتقدم إليه بعض الفريسيين وسألوه ليجربوه: «هل يحل للرجل أن يطلق زوجته؟»","10:3":"فرد عليهم سائلا:","10:4":"«بماذا أوصاكم موسى؟» فقالوا: «سمح موسى بأن تكتب وثيقة طلاق ثم تطلق الزوجة».","10:5":"فأجابهم يسوع: «بسبب قساوة قلوبكم كتب لكم موسى هذه الوصية.","10:6":"ولكن منذ بدء الخليقة جعل الله الإنسان ذكرا وأنثى.","10:7":"لذلك يترك الرجل أباه وأمه ويتحد بزوجته،","10:8":"فيصير الاثنان جسدا واحدا. فلا يكونان بعد اثنين بل جسدا واحدا.","10:9":"فما جمعه الله لا يفرقه إنسان».","10:10":"وفي البيت، عاد تلاميذه فسألوه عن الأمر.","10:11":"فقال لهم: «أي من طلق زوجته وتزوج بأخرى، يرتكب معها الزنى.","10:12":"وإن طلقت الزوجة زوجها وتزوجت من آخر، ترتكب الزنى! »","10:13":"وقدم إليه بعضهم أولادا صغارا لكي يلمسهم. فزجرهم التلاميذ.","10:14":"فلما رأى يسوع ذلك، غضب وقال لهم: «دعوا الصغار يأتون إلي، ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله!","10:15":"الحق أقول لكم: من لا يقبل ملكوت الله كأنه ولد صغير، لن يدخله أبدا!»","10:16":"ثم ضم الأولاد بذراعيه وأخذ يباركهم واضعا يديه عليهم.","10:17":"وبينما كان خارجا إلى الطريق، أسرع إليه رجل وجثا له يسأله: «أيها المعلم الصالح، ماذا أعمل لأرث الحياة الأبدية؟»","10:18":"ولكن يسوع قال له: «لماذا تدعوني الصالح؟ ليس أحد صالحا إلا واحد، وهو الله .","10:19":"أنت تعرف الوصايا: لا تقتل؛ لا تزن؛ لا تسرق؛ لا تشهد بالزور؛ لا تظلم؛ أكرم أباك وأمك!»","10:20":"فأجابه قائلا: «هذه كلها عملت بها منذ صغري»","10:21":"وإذ نظر يسوع إليه، أحبه، وقال له: «ينقصك شيء واحد: اذهب، بع كل ما عندك، ووزع على الفقراء، فيكون لك كنز في السماء، ثم تعال اتبعني».","10:22":"وأما هو فمضى حزينا وقد اكتأب من هذا القول، لأنه كان صاحب ثروة كبير ة.","10:23":"فتطلع يسوع حوله وقال لتلاميذه: «ما أصعب دخول الأغنياء إلى ملكوت الله!»","10:24":"فدهش التلاميذ لهذا الكلام. فعاد يسوع يقول لهم: «يابني، ما أصعب دخول المتكلين على المال إلى ملكوت الله!»","10:25":"فأسهل أن يدخل الجمل في ثقب إبرة، من أن يدخل الغني إلى ملكوت الله».","10:26":"فذهلوا إلى الغاية، وقال بعضهم لبعض: «ومن يقدر أن يخلص؟»","10:27":"فقال لهم يسوع وهو ناظر إليهم: «هذا مستحيل عند الناس، ولكن ليس عند الله. فإن كل شيء مستطاع عند الله! »","10:28":"فأخذ بطرس يقول له: «ها نحن قد تركنا كل شيء وتبعناك.»","10:29":"فأجاب يسوع: «الحق أقول لكم: ما من أحد ترك لأجلي ولأجل الإنجيل بيتا أو إخوة أو أخوات أو أما أو أبا أو أولادا أو حقولا،","10:30":"إلا وينال مئة ضعف الآن في هذا الزمان، وفي الزمان الآتي الحياة الأبدية.","10:31":"ولكن أولون كثيرون يصيرون آخرين، والآخرون يصيرون أولين! »","10:32":"وكانوا في الطريق صاعدين إلى أورشليم، ويسوع يتقدمهم، وهم يتبعونه مذهولين خائفين. فانفرد بالاثني عشر، مرة أخرى، وأخذ يطلعهم على ما سيحدث له، فقال:","10:33":"«ها نحن صاعدون إلى أورشليم، وسوف يسلم ابن الإنسان إلى رؤساء الكهنة وإلى الكتبة، فيحكمون عليه بالموت، ويسلمونه إلى أيدي الأمم،","10:34":"فيسخرون منه، ويبصقون عليه، ويجلدونه، ويقتلونه. وفي اليوم الثالث يقوم! »","10:35":"عندئذ تقدم إليه يعقوب ويوحنا ابنا زبدي، وقالا له: «يامعلم، نرغب في أن تفعل لنا كل ما نطلب منك».","10:36":"فسألهما: «ماذا ترغبان في أن أفعل لكما؟»","10:37":"قالا له: «هبنا أن نجلس في مجدك: واحد عن يمينك، وواحد عن يسارك!»","10:38":"فقال لهما يسوع: «أنتما لا تدريان ما تطلبان: أتقدران أن تشربا الكأس التي سأشربها أنا، أو تتعمدا بالمعمودية التي سأتعمد بها أنا؟»","10:39":"فقالا له: «إننا نقدر!» فأجابهما يسوع: «الكأس التي سأشربها سوف تشربان، وبالمعمودية التي سأتعمد بها سوف تتعمدان.","10:40":"أما الجلوس عن يميني وعن يساري، فليس لي أن أمنحه إلا للذين أعد لهم».","10:41":"ولما سمع التلاميذ العشرة بذلك، أخذوا يستاءون من يعقوب ويوحنا.","10:42":"ولكن يسوع دعاهم إليه وقال لهم: «تعرفون أن المعتبرين حكاما على الأمم يسودونهم، وأن عظماءهم يتسلطون عليهم.","10:43":"وأما أنتم فلا يكن ذلك بينكم، وإنما أي من أراد أن يصير عظيما بينكم، فليكن لكم خادما،","10:44":"وأي من أراد أن يصير أولا فيكم، فليكن للجميع عبدا.","10:45":"فحتى ابن الإنسان قد جاء لا ليخدم، بل ليخدم ويبذل نفسه فدية عن كثيرين».","10:46":"ثم وصلوا إلى أريحا. وبينما كان خارجا من أريحا، ومعه تلاميذه وجمع كبير، كان ابن تيماوس، بارتيماوس الأعمى، جالسا على جانب الطريق يستعطي.","10:47":"وإذ سمع أن ذاك هو يسوع الناصري، أخذ يصرخ قائلا: «يايسوع ابن داود، ارحمني!»","10:48":"فزجره كثيرون ليسكت، ولكنه أخذ يزيد صراخا أكثر: «ياابن داود، ارحمني».","10:49":"فتوقف يسوع وقال: «ادعوه!» فدعوا الأعمى قائلين: «تشجع، انهض! إنه يدعوك!»","10:50":"فهب متجها إلى يسوع طارحا عنه رداءه.","10:51":"وسأله يسوع: «ماذا تريد أن أفعل لك؟» فأجابه الأعمى: «ياسيدي، أن أبصر!»","10:52":"فقال له يسوع: «اذهب ! إيمانك قد شفاك». وفي الحال أبصر، وتبع يسوع في الطريق.","11:1":"ولما اقتربوا من أورشليم، إذ وصلوا إلى قرية بيت فاجي وقرية بيت عنيا، عند جبل الزيتون، أرسل يسوع اثنين من تلاميذه،","11:2":"قائلا لهما: «اذهبا إلى القرية المقابلة لكما، وحالما تدخلان إليها، تجدان جحشا مربوطا لم يركب عليه أحد من الناس بعد: فحلا رباطه وأحضراه إلى هنا.","11:3":"وإن قال لكما أحد: لماذا تفعلان هذا؟ فقولا: الرب بحاجة إليه، وفي الحال يرسله إلى هنا».","11:4":"وانطلقا، فوجدا الجحش مربوطا عند الباب خارجا على الطريق، فحلا رباطه.","11:5":"فقال لهما بعض الواقفين هناك: «ماذا تفعلان؟ لماذا تحلان رباط الجحش؟»","11:6":"فأجاباهم كما أوصاهما يسوع فتركوهما.","11:7":"فأحضرا الجحش إلى يسوع، ووضعا ثيابهما عليه، فركب عليه.","11:8":"وفرش كثيرون الطريق بثيابهم وآخرون بأغصان قطعوها من الحقول.","11:9":"وأخذ السائرون أمامه والسائرون خلفه يهتفون: «أوصنا! مبارك الآتي باسم الرب !","11:10":"مباركة مملكة أبينا داود الآتية! أوصنا في الأعالي! »","11:11":"ثم دخل يسوع أورشليم، حتى وصل إلى الهيكل، وراقب كل ما كان يجري فيه. وإذ كان المساء قد أقبل، خرج إلى بيت عنيا مع الاثني عشر.","11:12":"وفي الغد، بعدما غادروا بيت عنيا، جاع.","11:13":"وإذ رأى من بعيد شجرة تين مورقة، توجه إليها لعله يجد فيها بعض الثمر. فلما وصل إليها لم يجد فيها إلا الورق، لأنه ليس أوان التين.","11:14":"فتكلم وقال لها: «لا يأكلن أحد ثمرا منك بعد إلى الأبد!» وسمع تلاميذه ذلك.","11:15":"ووصلوا إلى أورشليم، فدخل يسوع الهيكل وأخذ يطرد الذين كانوا يبيعون والذين كانوا يشترون في الهيكل، وقلب موائد الصيارفة ومقاعد باعة الحمام.","11:16":"ولم يدع أحدا يمر عبر الهيكل وهو يحمل متاعا.","11:17":"وعلمهم قائلا: «أما كتب: إن بيتي بيتا للصلاة يدعى عند جميع الأمم؟ أما أنتم فقد جعلتموه مغارة لصوص!»","11:18":"وسمع بذلك رؤساء الكهنة، والكتبة، فأخذوا يبحثون كيف يقتلونه: فإنهم خافوه، لأن الجمع كله كان مذهولا من تعليمه.","11:19":"ولما حل المساء، انطلقوا إلى خارج المدينة.","11:20":"وبينما كانوا عابرين في صباح الغد باكرا، رأوا شجرة التين وقد يبست من أصلها.","11:21":"فتذكر بطرس وقال له: «يامعلم، انظر! إن التينة التي لعنتها قد يبست!»","11:22":"فرد يسوع قائلا لهم: «ليكن لكم إيمان بالله!","11:23":"فالحق أقول لكم: إن أي من قال لهذا الجبل: انقلع وانطرح في البحر! ولا يشك في قلبه، بل يؤمن أن ما يقوله سيحدث، فما يقوله يتم له.","11:24":"لهذا السبب أقول لكم: إن ما تطلبونه وتصلون لأجله، فآمنوا أنكم قد نلتموه، فيتم لكم.","11:25":"ومتى وقفتم تصلون، وكان لكم على أحد شيء، فاغفروا له، لكي يغفر لكم أبوكم الذي في السماوات زلاتكم أيضا.","11:26":"ولكن، إن لم تغفروا، لا يغفر لكم أيضا أبوكم الذي في السماوات زلاتكم».","11:27":"ثم عادوا إلى أورشليم مرة أخرى. وبينما كان يتجول في الهيكل، تقدم إليه رؤساء الكهنة، والكتبة، والشيوخ،","11:28":"وسألوه: «بأية سلطة تفعل ما فعلته؟ ومن منحك هذه السلطة لتفعل ذلك؟»","11:29":"فأجابهم يسوع قائلا: «وأنا أيضا أسألكم أمرا واحدا. أجيبوني، فأقول لكم بأية سلطة أفعل تلك الأمور:","11:30":"أمن السماء كانت معمودية يوحنا أم من الناس؟ أجيبوني!»","11:31":"فتشاوروا فيما بينهم، قائلين: «إن قلنا: من السماء، يقول: إذن لماذا لم تؤمنوا به؟","11:32":"فهل نقول: من الناس؟» فإنهم كانوا يخافون الشعب لأنهم كانوا جميعا يعتبرون أن يوحنا نبي حقا.","11:33":"فأجابوا يسوع قائلين: «لا ندري!» فقال لهم يسوع: «ولا أنا أقول لكم بأية سلطة أفعل تلك الأمور! »","12:1":"وأخذ يخاطبهم بأمثال، فقال: «غرس إنسان كرما، وأقام حوله سياجا، وحفر فيه حوض معصرة، وبنى فيه برج حراسة. ثم سلم الكرم إلى مزارعين، وسافر.","12:2":"وفي الأوان، أرسل إلى المزارعين عبدا ليتسلم منهم حصته من ثمر الكرم.","12:3":"إلا أنهم أمسكوه وضربوه وردوه فارغ اليدين.","12:4":"فعاد وأرسل إليهم عبدا آخر، فشجوا رأسه وردوه مهانا.","12:5":"ثم أرسل آخر أيضا فقتلوه. ثم أرسل آخرين كثيرين، فضربوا بعضا وقتلوا بعضا.","12:6":"وإذ كان له بعد ابن وحيد حبيب، أرسله أيضا إليهم أخيرا، قائلا: إنهم سيهابون ابني!","12:7":"ولكن أولئك المزارعين قالوا بعضهم لبعض: هذا هو الوريث؛ تعالوا نقتله فنحصل على الميراث!","12:8":"فأمسكوه وقتلوه وطرحوه خارج الكرم.","12:9":"فماذا يفعل رب الكرم؟ إنه يأتي ويهلك المزارعين، ويسلم الكرم إلى غيرهم.","12:10":"أفما قرأ تم هذه الآية المكتوبة: الحجر الذي رفضه البناة، هو نفسه صار حجر الزاوية.","12:11":"من الرب كان هذا، وهو عجيب في أنظارنا!»","12:12":"فسعوا إلى القبض عليه، ولكنهم خافوا الجمع، لأنهم أدركوا أنه كان يعنيهم بهذا المثل. فتركوه وانصرفوا.","12:13":"ثم أرسلوا إليه بعضا من الفريسيين وأعضاء حزب هيرودس، لكي يوقعوه بكلمة يقولها.","12:14":"فجاءوا وقالوا له: «يامعلم، نحن نعلم أنك صادق، ولا تبالي بأحد، لأنك لا تراعي مقامات الناس، بل تعلم طريق الله بالحق: أيحل أن تدفع الجزية للقيصر أم لا؟ أندفعها أم لا ندفع؟»","12:15":"ولكنه إذ علم رياءهم قال لهم: «لماذا تجربونني؟ أحضروا إلي دينارا لأراه!»","12:16":"فأحضروا إليه دينارا، فسألهم: «لمن هذه الصورة وهذا النقش؟» فقالوا له: «للقيصر».","12:17":"فرد عليهم قائلا: «أعطوا ما للقيصر للقيصر، وما لله لله!» فذهلوا منه.","12:18":"وتقدم إليه بعض الصدوقيين الذين لا يؤمنون بالقيامة، وسألوه قائلين:","12:19":"«يامعلم، كتب لنا موسى: إن مات لأحد أخ وترك زوجته من بعده دون أن يخلف أولادا، فعلى أخيه أن يتزوج بأرملته ويقيم نسلا على اسم أخيه.","12:20":"فقد كان هنالك سبعة إخوة، اتخذ أولهم زوجة ثم مات دون أن يخلف نسلا،","12:21":"فاتخذها الثاني ثم مات هو أيضا دون أن يخلف نسلا، ففعل الثالث كذلك.","12:22":"وهكذا اتخذها السبعة دون أن يخلفوا نسلا. ومن بعدهم جميعا، ماتت المرأة أيضا.","12:23":"ففي القيامة، عندما يقومون، لمن منهم تكون المرأة زوجة، فقد كانت زوجة لكل من السبعة؟»","12:24":"فرد عليهم يسوع قائلا: «ألستم في ضلال لأنكم لا تفهمون الكتاب ولا قدرة الله؟","12:25":"فعندما يقوم الناس من بين الأموات، لا يتزوجون ولا يزوجون، بل يكونون كالملائكة الذين في السماوات.","12:26":"وأما عن الأموات أنهم يقومون، أفما قرأتم في كتاب موسى، في الحديث عن العليقة، كيف كلمه الله قائلا: أنا إله إبراهيم وإله إسحق وإله يعقوب؟","12:27":"فإنه ليس بإله أموات، بل هو إله أحياء. فأنتم إذن في ضلال عظيم! »","12:28":"وتقدم إليه واحد من الكتبة كان قد سمعهم يتجادلون، ورأى أنه أحسن الرد عليهم، فسأله: «أية وصية هي أولى الوصايا جميعا؟»","12:29":"فأجابه يسوع: «أولى الوصايا جميعا هي: اسمع ياإسرائيل، الرب إلهنا رب واحد","12:30":"فأحب الرب إلهك بكل قلبك وبكل نفسك وبكل فكرك وبكل قوتك. هذه هي الوصية الأولى.","12:31":"وهناك ثانية مثلها، وهي أن تحب قريبك كنفسك. فما من وصية أخرى أعظم من هاتين».","12:32":"فقال له الكاتب: «صحيح، يامعلم! حسب الحق تكلمت. فإن الله واحد وليس آخر سواه.","12:33":"ومحبته بكل القلب وبكل الفهم وبكل القوة، ومحبة القريب كالنفس، أفضل من جميع المحرقات والذبائح!»","12:34":"فلما رأى يسوع أنه أجاب بحكمة، قال له: «لست بعيدا عن ملكوت الله!» ولم يجرؤ أحد بعد ذلك أن يوجه إليه أي سؤال.","12:35":"وتكلم يسوع فيما هو يعلم في الهيكل، فقال: «كيف يقول الكتبة إن المسيح هو ابن داود؟","12:36":"فإن داود نفسه قال بالروح القدس: قال الرب لربي: اجلس عن يميني حتى أضع أعداءك موطئا لقدميك!","12:37":"فمادام داود نفسه يدعوه الرب فمن أين يكون ابنه؟» وكان الجمع العظيم يسمعه بسرور.","12:38":"وقال لهم في تعليمه: «خذوا حذركم من الكتبة الذين يحبون التجول بالأثواب الفضفاضة، وتلقي التحيات في الساحات العامة،","12:39":"وصدور المقاعد في المجامع، وأماكن الصدارة في الولائم.","12:40":"يلتهمون بيوت الأرامل، ويتذرعون بإطالة الصلوات. هؤلاء ستنزل بهم دينونة أقسى! »","12:41":"وإذ جلس يسوع مقابل صندوق الهيكل، رأى كيف كان الجمع يلقون النقود في الصندوق. وألقى كثيرون من الأغنياء مالا كثيرا.","12:42":"ثم جاءت أرملة فقيرة وألقت فلسين يساويان ربعا واحدا.","12:43":"فدعا تلاميذه وقال لهم: «الحق أقول لكم: إن هذه الأرملة الفقيرة قد ألقت أكثر من جميع الذين ألقوا في الصندوق:","12:44":"لأن جميعهم ألقوا من الفاضل عن حاجتهم، ولكنها هي ألقت من حاجتها كل ما عندها ألقت معيشتها كلها ! »","13:1":"وبينما كان يغادر الهيكل، قال له أحد تلاميذه: «يامعلم، انظر ما أجمل هذه الحجارة وهذه المباني!»","13:2":"فأجابه يسوع: «أترى هذه المباني العظيمة؟ لن يترك منها حجر فوق حجر إلا ويهدم! »","13:3":"وفيما هو جالس على جبل الزيتون مقابل الهيكل، سأله بطرس ويعقوب ويوحنا وأندراوس على انفراد:","13:4":"«أخبرنا متى يحدث هذا، وما هي العلامة عندما توشك هذه الأمور أن تتم؟»","13:5":"فأخذ يسوع يجيبهم قائلا: «انتبهوا! لا يضللكم أحد!","13:6":"فإن كثيرين سيأتون باسمي قائلين، إني أنا هو ويضللون كثيرين.","13:7":"ولكن، عندما تسمعون بالحروب وأخبار الحروب لا ترتعبوا؛ فإن ذلك لابد أن يحدث، ولكن ليست النهاية بعد.","13:8":"فسوف تنقلب أمة على أمة، ومملكة على مملكة، وتحدث زلازل في عدة أماكن، كما تحدث مجاعات ولكن هذا أول المخاض.","13:9":"فانتبهوا لأنفسكم، لأنهم سوف يسلمونكم إلى المحاكم والمجامع، فتضربون وتمثلون أمام حكام وملوك من أجلي، شهادة عندهم.","13:10":"ويجب أن يبشر أولا بالإنجيل في جميع الأمم.","13:11":"فعندما يسوقونكم ليسلموكم، لا تنشغلوا مسبقا بما تقولون: وإنما كل ما تلهمون في تلك الساعة، فبه تكلموا، لأنكم لستم أنتم المتكلمين بل الروح القدس.","13:12":"وسوف يسلم الأخ أخاه إلى الموت، والأب ولده، وينقلب الأولاد على والديهم ويقتلونهم.","13:13":"وتكونون مكروهين لدى الجميع من أجل اسمي. ولكن الذي يثبت حتى النهاية، فهو يخلص.","13:14":"فعندما ترون رجاسة الخراب قائمة حيث لا ينبغي، ليفهم القاريء! عندئذ ليهرب الذين في منطقة اليهودية إلى الجبال؛","13:15":"ومن كان على السطح، فلا ينزل إلى البيت ولا يدخل ليأخذ ما في بيته؛","13:16":"ومن كان في الحقل، فلا يرجع ليأخذ ثوبه.","13:17":"والويل للحبالى والمرضعات في تلك الأيام!","13:18":"فصلوا لكي لا يقع ذلك في شتاء:","13:19":"فسوف تحدث في تلك الأيام ضيقة لم يحدث مثلها منذ بدء الخليقة التي خلقها الله إلى الآن ولن يحدث.","13:20":"ولولا أن الرب قد اختصر تلك الأيام، لما كان أحد من البشر ينجو. ولكنه لأجل المختارين الذين اختارهم، قد اختصر تلك الأيام.","13:21":"فإن قال لكم أحد عندئذ: ها إن المسيح هنا! أو: ها هو هناك! فلا تصدقوا.","13:22":"فسوف يبرز أكثر من مسيح دجال ونبي دجال، ويقدمون آيات وأعاجيب، ليضللوا حتى المختارين، لو استطاعوا.","13:23":"فانتبهوا إذن! ها أنا قد أخبرتكم بالأمور كلها قبل حدوثها.","13:24":"ولكن في تلك الأيام، بعد تلك الضيقة، تظلم الشمس ويحجب القمر ضوءه،","13:25":"وتتهاوى نجوم السماء، وتتزعزع القوات التي في السماوات.","13:26":"وعندئذ سوف يبصرون ابن الإنسان آتيا في السحب بقدرة عظيمة ومجد.","13:27":"فيرسل عندئذ ملائكته ويجمع مختاريه من الجهات الأربع، من أقصى الأرض إلى أقصى السماء.","13:28":"فمن شجرة التين تعلموا هذا المثل: عندما تلين أغصانها وتطلع أوراقها، تعلمون أن الصيف قريب.","13:29":"فكذلك أنتم أيضا، حينما ترون هذه الأمور تحدث، فاعلموا أنه قريب، بل على الأبواب.","13:30":"الحق أقول لكم: لا يزول هذا الجيل أبدا حتى تحدث هذه الأمور كلها.","13:31":"إن السماء والأرض تزولان، ولكن كلامي لا يزول أبدا.","13:32":"وأما ذلك اليوم وتلك الساعة فلا يعرفهما أحد، لا الملائكة الذين في السماء ولا الابن، إلا الآب.","13:33":"فانتبهوا واسهروا لأنكم لا تعرفون متى يحين الوقت!","13:34":"فالأمر أشبه بإنسان مسافر، ترك بيته، وأعطى عبيده السلطة معينا لكل واحد عمله، وأوصى حارس الباب أن يسهر.","13:35":"إذن اسهروا، لأنكم لا تعرفون متى يعود رب البيت: أمساء، أم في منتصف الليل، أم عند صياح الديك، أم صباحا،","13:36":"لئلا يعود فجأة ويجدكم نائمين.","13:37":"وما أقوله لكم، أقوله للجميع: اسهروا! »","14:1":"وكان الفصح وعيد الفطير سيحلان بعد يومين، ومازال رؤساء الكهنة والكتبة يسعون كي يقبضوا عليه بمكر ويقتلوه.","14:2":"فإ نهم قد قالوا: «لا يكون ذلك في العيد، لئلا يحدث اضطراب بين الشعب! »","14:3":"وفيما كان يسوع في بيت عنيا، متكئا في بيت سمعان الأبرص، جاءت امرأة تحمل قارورة عطر من الناردين الخالص الغالي الثمن، فكسرت القارورة وسكبت العطر على رأسه.","14:4":"فاستاء بعضهم في أنفسهم وقالوا: «لماذا هذا التبذير للعطر؟","14:5":"فقد كان يمكن أن يباع هذا العطر بأكثر من ثلاث مئة دينار، ويوهب الثمن للفقراء». وأخذوا يؤنبون المرأة.","14:6":"غير أن يسوع قال: «اتركوها! لماذا تضايقونها؟ إنها عملت بي عملا حسنا.","14:7":"فإن الفقراء عندكم في كل حين، ومتى شئتم تستطيعون أن تحسنوا إليهم. أما أنا فلن أكون عندكم في كل حين.","14:8":"إنها عملت ما تقدر عليه. فقد سبقت فعطرت جسدي إعدادا للدفن.","14:9":"والحق أقول لكم: إنه حيث يبشر بالإنجيل في العالم أجمع، يحدث أيضا بما عملته هذه المرأة، إحياء لذكرها! »","14:10":"ثم ذهب يهوذا الإسخريوطي، أحد الاثني عشر، إلى رؤساء الكهنة ليسلم يسوع إليهم.","14:11":"فلما سمعوا بذلك، فرحوا، ووعدوه أن يعطوه مالا. فأخذ يتحين تسليمه في فرصة مناسبة.","14:12":"وفي اليوم الأول من أيام الفطير، وفيه كان يذبح (حمل) الفصح، سأله تلاميذه: «أين تريد أن نذهب ونجهز لك الفصح لتأكل؟»","14:13":"فأرسل اثنين من تلاميذه، قائلا لهما: «اذهبا إلى المدينة، وسيلاقيكما هناك رجل يحمل جرة ماء، فاتبعاه.","14:14":"وحيث يدخل، قولا لرب البيت: إن المعلم يقول: أين غرفتي التي فيها سآكل الفصح مع تلاميذي؟","14:15":"فيريكما غرفة كبيرة في الطبقة العليا، مفروشة مجهزة. هناك جهزا لنا!»","14:16":"فانطلق التلميذان ودخلا المدينة، ووجدا كما قال لهما. وهناك جهزا للفصح.","14:17":"ولما حل المساء، جاء يسوع مع الاثني عشر.","14:18":"وبينما كانوا متكئين يأكلون، قال يسوع: «الحق أقول لكم: إن واحدا منكم سيسلمني، وهو يأكل الآن معي».","14:19":"فأخذ الحزن يستولي عليهم، وبدأوا يسألونه واحدا بعد الآخر: «هل أنا؟»","14:20":"ولكنه أجابهم قائلا: «إنه واحد من الاثني عشر، وهو الذي يغمس معي في الصحفة.","14:21":"إن ابن الإنسان لابد أن يمضي كما قد كتب عنه، ولكن الويل لذلك الرجل الذي على يده يسلم ابن الإنسان. كان خيرا لذلك الرجل لو لم يولد! »","14:22":"وبينما كانوا يأكلون، أخذ يسوع رغيفا، وبارك، وكسر، وأعطاهم قائلا: «خذوا: هذا هو جسدي».","14:23":"ثم أخذ الكأس، وشكر، وأعطاهم، فشربوا منها كلهم،","14:24":"وقال لهم: «هذا هو دمي الذي للعهد الجديد والذي يسفك من أجل كثيرين.","14:25":"الحق أقول لكم: لا أشرب بعد من نتاج الكرمة أبدا، إلى ذلك اليوم الذي أشربه فيه جديدا في ملكوت الله».","14:26":"ثم رتلوا، وانطلقوا خارجا إلى جبل الزيتون.","14:27":"وقال لهم يسوع: «كلكم ستشكون، لأنه قد كتب: سأضرب الراعي، فتتشتت الخراف.","14:28":"ولكن بعد قيامتي، سأسبقكم إلى الجليل».","14:29":"ولكن بطرس قال له: «ولو شك الجميع، فأنا لن أشك».","14:30":"فقال له يسوع: «الحق أقول لك: إنك اليوم، في هذه الليلة، قبل أن يصيح الديك مرتين، تكون قد أنكرتني ثلاث مرات».","14:31":"إلا أن بطرس قال بأكثر تأكيد: «ولو كان علي أن أموت معك، لا أنكرك أبدا!» وقال التلاميذ كلهم مثل هذا القول.","14:32":"ووصلوا إلى بستان اسمه جثسيماني، فقال لتلاميذه: «اجلسوا هنا ريثما أصلي».","14:33":"وقد أخذ معه بطرس ويعقوب ويوحنا، وبدأ يشعر بالرهبة والكآبة.","14:34":"وقال لهم: «نفسي حزينة جدا حتى الموت. ابقوا هنا واسهروا».","14:35":"ثم ابتعد قليلا، وخر على الأرض، وأخذ يصلي لكي تعبر عنه الساعة إن كان ممكنا.","14:36":"وقال «أبا، ياأبي، كل شيء مستطاع لديك. فأبعد عني هذه الكأس، ولكن ليكن لا ما أريد أنا، بل ما تريد أنت! »","14:37":"ثم رجع فوجد تلاميذه نائمين، فقال لبطرس: «هل أنت نائم ياسمعان؟ ألم تقدر أن تسهر ساعة واحدة؟","14:38":"اسهروا وصلوا لئلا تدخلوا في تجربة. إن الروح نشيط، وأما الجسد فضعيف».","14:39":"ثم ذهب وصلى ثانية، فردد الكلام نفسه.","14:40":"ولما رجع، وجدهم أيضا نائمين لأن النعاس أثقل أعينهم، ولم يدروا بماذا يجيبونه.","14:41":"ثم رجع في المرة الثالثة وقال لهم: «ناموا الآن واستريحوا. يكفي! أقبلت الساعة. ها إن ابن الإنسان يسلم إلى أيدي الخاطئين.","14:42":"قوموا لنذهب. ها قد اقترب الذي يسلمني! »","14:43":"وفي الحال، فيما هو يتكلم، وصل يهوذا، أحد الاثني عشر، ومعه جمع عظيم يحملون السيوف والعصي، وقد أرسلهم رؤساء الكهنة والكتبة والشيوخ.","14:44":"وكان مسلمه قد أعطاهم علامة قائلا: «الذي أقبله، فهو هو. فاقبضوا عليه وسوقوه بحذر».","14:45":"فما إن وصل يهوذا، حتى تقدم إليه، وقال: «سيدي!» وقبله بحرارة.","14:46":"فألقوا القبض عليه.","14:47":"ولكن واحدا من الواقفين هناك، استل سيفه وضرب عبد رئيس الكهنة فقطع أذنه.","14:48":"وكلمهم يسوع قائلا: «أكما على لص خرجتم بالسيوف والعصي لتقبضوا علي؟","14:49":"كنت كل يوم بينكم أعلم في الهيكل، ولم تقبضوا علي. ولكن هذا يجري إتماما للكتاب».","14:50":"عندئذ تركه الجميع وهربوا.","14:51":"وتبعه شاب لا يلبس غير إزار على عريه، فأمسكوه.","14:52":"فترك الإزار وهرب منهم عريانا.","14:53":"وساقوا يسوع إلى رئيس الكهنة. فاجتمع إليه جميع رؤساء الكهنة والشيوخ والكتبة.","14:54":"وتبعه بطرس من بعيد إلى داخل دار رئيس الكهنة، وكان جالسا مع الحراس يستدفيء عند النار.","14:55":"وأخذ رؤساء الكهنة والمجلس الأعلى كله يبحثون عن شهادة على يسوع ليقتلوه، فلم يجدوا.","14:56":"فقد شهد كثيرون عليه زورا، ولكن شهاداتهم كانت متناقضة.","14:57":"ثم قام بعضهم وشهدوا عليه زورا قائلين:","14:58":"«سمعناه يقول: سأهدم هذا الهيكل الذي صنعته الأيادي، وفي ثلاثة أيام أبني هيكلا آخر لم تصنعه الأيادي».","14:59":"ولكن في هذا أيضا، كانت شهاداتهم متناقضة.","14:60":"فوقف رئيس الكهنة في وسط المجلس وسأل يسوع: «أما ترد شيئا؟ بماذا يشهد هؤلاء عليك؟»","14:61":"ولكنه ظل صامتا ولم يرد شيئا. فعاد رئيس الكهنة يسأله، فقال: «أأنت المسيح، ابن المبارك؟»","14:62":"فقال يسوع: «أنا هو. وسوف ترون ابن الإنسان جالسا عن يمين القدرة، ثم آتيا على سحب السماء! »","14:63":"فشق رئيس الكهنة ثيابه، وقال: «لا حاجة بنا بعد إلى شهود.","14:64":"قد سمعتم تجديفه: فما رأيكم؟» فحكم الجميع بأنه يستحق الموت.","14:65":"فبدأ بعضهم يبصقون عليه، ويغطون وجهه ويلطمونه ويقولون له: «تنبأ!» وأخذ الحراس يصفعونه.","14:66":"وبينما كان بطرس تحت في ساحة الدار، جاءت إحدى خادمات رئيس الكهنة،","14:67":"فلما رأت بطرس يستدفيء، نظرت إليه وقالت: «وأنت كنت مع يسوع الناصري!»","14:68":"ولكنه أنكر قائلا: «لا أدري ولا أفهم ما تقولين!» ثم ذهب خارجا إلى مدخل الدار. فصاح الديك","14:69":"وإذ رأته الخادمة ثانية، أخذت تقول للواقفين هناك: «هذا واحد منهم!»","14:70":"فأنكر ثانية. وبعد قليل أيضا، قال الواقفون هناك لبطرس: «حقا أنت واحد منهم، لأنك جليلي».","14:71":"ولكنه بدأ يلعن ويحلف: «إني لا أعرف هذا الرجل الذي تتحدثون عنه».","14:72":"وصاح الديك مرة ثانية فتذكر بطرس ما قاله يسوع له: «قبل أن يصيح الديك مرتين، تكون قد أنكرتني ثلاث مرات». وإذ تفكر بذلك أخذ يبكي.","15:1":"وحالما طلع الصباح، تشاور رؤساء الكهنة والشيوخ والكتبة والمجلس الأعلى كله، ثم قيدوا يسوع، وساقوه، وسلموه إلى بيلاطس.","15:2":"فسأله بيلاطس: «أأنت ملك اليهود؟» فأجابه: «أنت قلت».","15:3":"وأخذ رؤساء الكهنة يوجهون إليه اتهامات كثيرة.","15:4":"فسأله بيلاطس ثانية: «أما ترد شيئا؟ انظر ما يشهدون به عليك!»","15:5":"ولكن يسوع لم يرد شيئا، حتى تعجب بيلاطس.","15:6":"وكان من عادته أن يطلق لهم في العيد أي سجين يطلبونه.","15:7":"وكان المدعو باراباس مسجونا عندئذ مع رفاقه المشاغبين الذين ارتكبوا القتل في أثناء الشغب.","15:8":"فصعد الجمع وأخذوا يطالبون بأن يفعل بيلاطس ما كان يفعله لهم دائما.","15:9":"فكلمهم بيلاطس سائلا: «هل تريدون أن أطلق لكم ملك اليهود؟»","15:10":"لأنه علم أن رؤساء الكهنة كانوا قد سلموه عن حسد.","15:11":"ولكن رؤساء الكهنة حرضوا الجمع على أن يطالبوا، بالأحرى، بإطلاق باراباس.","15:12":"فعاد بيلاطس يسألهم: «فماذا تريدون أن أفعل بمن تدعونه ملك اليهود؟»","15:13":"فراحوا يصرخون مرة بعد مرة: «اصلبه !»","15:14":"فسألهم بيلاطس: «وأي شر فعل؟» إلا أنهم أخذوا يزدادون صراخا: «اصلبه!»","15:15":"وإذ كان بيلاطس يريد أن يرضي الجمع، أطلق لهم باراباس، وبعد ما جلد يسوع، سلمه ليصلب.","15:16":"فاقتاده الجنود إلى داخل الدار، أي دار الحكومة، وجمعوا جنود الكتيبة كلهم.","15:17":"وألبسوه رداء أرجوان، ووضعوا على رأسه إكليلا جدلوه من الشوك.","15:18":"وبدأوا يحيونه قائلين: «سلام، ياملك اليهود!»","15:19":"ويضربون رأسه بقصبة، ويبصقون عليه، ويسجدون له جاثين على ركبهم.","15:20":"وبعدما أوسعوه سخرية، نزعوا رداء الأرجوان، وألبسوه ثيابه، وساقوه إلى الخارج ليصلبوه.","15:21":"وسخروا واحدا من المارة ليحمل صليبه، وهو سمعان من القيروان، أبو إسكندر وروفس، وكان آتيا من الحقل.","15:22":"وساروا به إلى مكان الجلجثة، أي مكان الجمجمة.","15:23":"وقدموا له خمرا ممزوجة بمر، فرفض أن يشرب.","15:24":"وبعدما صلبوه تقاسموا ثيابه، مقترعين عليها لمعرفة نصيب كل منهم.","15:25":"وكانت الساعة التاسعة صباحا حينما صلبوه.","15:26":"وكان عنوان تهمته مكتوبا: «ملك اليهود».","15:27":"وصلبوا معه لصين، واحدا عن يمينه، وواحدا عن يساره.","15:28":"فتمت الآية القائلة: «وأحصي مع المجرمين».","15:29":"وكان المارة يشتمونه، وهم يهزون رؤوسهم قائلين: «هه! ياهادم الهيكل وبانيه في ثلاثة أيام،","15:30":"خلص نفسك، وانزل عن الصليب!»","15:31":"كذلك كان رؤساء الكهنة أيضا يسخرون منه مع الكتبة قائلين بعضهم لبعض: «خلص غيره، وأما نفسه فلا يقدر أن يخلص.","15:32":"لينزل الآن المسيح ملك إسرائيل من على الصليب، لنرى ونؤمن!» وعيره أيضا اللصان المصلوبان معه.","15:33":"ولما جاءت الساعة الثانية عشرة ظهرا، حل الظلام على الأرض كلها حتى الساعة الثالثة بعد الظهر.","15:34":"وفي الساعة الثالثة، صرخ يسوع بصوت عظيم: «ألوي ألوي، لما شبقتني؟» أي: «إلهي إلهي، لماذا تركتني؟»","15:35":"فقال بعض الواقفين هناك لما سمعوا ذلك: «ها إنه ينادي إيليا!»","15:36":"وإذا واحد قد ركض وغمس إسفنجة في الخل وثبتها على قصبة وقدمها إليه ليشرب، قائلا: «دعوه! لنر هل يأتي إيليا لينزله! »","15:37":"فصرخ يسوع بصوت عظيم، وأسلم الروح.","15:38":"فانشق ستار الهيكل شطرين من أعلى إلى أسفل.","15:39":"فلما رأى قائد المئة الواقف مقابله أنه صرخ وأسلم الروح، قال: «حقا، كان هذا الإنسان ابن الله!»","15:40":"ومن بعيد كانت نساء كثيرات يراقبن ما يجري، وبينهن مريم المجدلية ومريم أم يعقوب الصغير ويوسى، وسالومة،","15:41":"اللواتي كن يتبعنه ويخدمنه عندما كان في الجليل، وغيرهن كثيرات كن قد صعدن معه إلى أورشليم.","15:42":"وإذ كان المساء قد حل، واليوم يوم الإعداد، أي ما قبل السبت،","15:43":"جاء يوسف الذي من الرامة، وهو عضو محترم في المجلس الأعلى، وكان هو أيضا ينتظر ملكوت الله، فتجرأ ودخل إلى بيلاطس، وطلب جثمان يسوع.","15:44":"فدهش بيلاطس من أنه قد مات، واستدعى قائد المئة واستفسره: هل مات منذ وقت طويل","15:45":"ولما أعلمه قائد المئة بذلك وهب يوسف الجثمان.","15:46":"وإذ اشترى يوسف كتانا وأنزل الجثمان، لفه بالكتان، ودفنه في قبر كان قد نحت في الصخر، ثم دحرج حجرا على باب القبر.","15:47":"وكانت مريم المجدلية ومريم أم يوسي تنظران أين دفن.","16:1":"ولما انتهى السبت، اشترت مريم المجدلية ومريم أم يعقوب وسالومة طيوبا عطرية ليأتين ويدهنه.","16:2":"وفي اليوم الأول من الأسبوع، أتين إلى القبر باكرا جدا مع طلوع الشمس.","16:3":"وكن يقلن بعضهن لبعض: «من يدحرج لنا الحجر من على باب القبر؟»","16:4":"لكنهن تطلعن فرأين أن الحجر قد دحرج، مع أنه كان كبيرا جدا.","16:5":"وإذ دخلن القبر، رأين في الجهة اليمنى شابا جالسا، لابسا ثوبا أبيض، فتملكهن الخوف.","16:6":"فقال لهن: «لا تخفن. أنتن تبحثن عن يسوع الناصري الذي صلب. إنه قام! ليس هو هنا. ها هو المكان الذي كان موضوعا فيه.","16:7":"لكن اذهبن وقلن لتلاميذه، ولبطرس، إنه سيسبقكم إلى الجليل؛ هناك ترونه كما قال لكم».","16:8":"فخرجن هاربات من القبر، وقد استولت عليهن الرعدة والدهشة الشديدة. ولم يقلن شيئا لأحد، لأنهن كن خائفات.","16:9":"وبعدما قام يسوع باكرا في اليوم الأول من الأسبوع، ظهر أولا لمريم المجدلية التي كان قد طرد منها سبعة شياطين.","16:10":"فذهبت وبشرت الذين كانوا معه، وقد كانوا ينوحون ويبكون.","16:11":"فلما سمع هؤلاء أنه حي وأنها قد شاهدته، لم يصدقوا.","16:12":"وبعد ذلك ظهر بهيئة أخرى لاثنين منهم وهما سائران منطلقين إلى إحدى القرى.","16:13":"فذهبا وبشرا الباقين، فلم يصدقوهما أيضا.","16:14":"أخيرا ظهر للأحد عشر تلميذا فيما كانوا متكئين، ووبخهم على عدم إيمانهم وقساوة قلوبهم، لأنهم لم يصدقوا الذين شاهدوه بعد قيامته.","16:15":"وقال لهم: «اذهبوا إلى العالم أجمع، وبشروا الخليقة كلها بالإنجيل:","16:16":"من آمن وتعمد، خلص، ومن لم يؤمن فسوف يدان.","16:17":"وأولئك الذين آمنوا، تلازمهم هذه الآيات: باسمي يطردون الشياطين ويتكلمون بلغات جديدة عليهم،","16:18":"ويقبضون على الحيات، وإن شربوا شرابا قاتلا لا يتأذون البتة، ويضعون أيديهم على المرضى فيتعافون».","16:19":"ثم إن الرب، بعدما كلمهم، رفع إلى السماء، وجلس عن يمين الله.","16:20":"وأما هم، فانطلقوا يبشرون في كل مكان، والرب يعمل معهم ويؤيد الكلمة بالآيات الملازمة لها."};
